class Solution:
    def totalNQueens(self, n: int) -> int:
        count = 0
        cols = [False] * n
        diag1 = [False] * (2 * n)
        diag2 = [False] * (2 * n)
        def backtrack(r: int):
            nonlocal count
            if r == n:
                count += 1
                return
            for c in range(n):
                if cols[c] or diag1[r - c + n] or diag2[r + c]:
                    continue
                cols[c] = diag1[r - c + n] = diag2[r + c] = True
                backtrack(r + 1)
                cols[c] = diag1[r - c + n] = diag2[r + c] = False
        backtrack(0)
        return count

class Solution {
public:
    int totalNQueens(int n) {
        int count = 0;
        vector<bool> cols(n, false), diag1(2 * n, false), diag2(2 * n, false);
        auto dfs = [&](auto& self, int r) -> void {
            if (r == n) {
                ++count;
                return;
            }
            for (int c = 0; c < n; ++c) {
                if (cols[c] || diag1[r - c + n] || diag2[r + c]) continue;
                cols[c] = diag1[r - c + n] = diag2[r + c] = true;
                self(self, r + 1);
                cols[c] = diag1[r - c + n] = diag2[r + c] = false;
            }
        };
        dfs(dfs, 0);
        return count;
    }
};

class Solution {
    private int count = 0;
    public int totalNQueens(int n) {
        count = 0;
        boolean[] cols = new boolean[n];
        boolean[] diag1 = new boolean[2 * n];
        boolean[] diag2 = new boolean[2 * n];
        dfs(0, n, cols, diag1, diag2);
        return count;
    }
    private void dfs(int r, int n, boolean[] cols, boolean[] diag1, boolean[] diag2) {
        if (r == n) {
            count++;
            return;
        }
        for (int c = 0; c < n; c++) {
            if (cols[c] || diag1[r - c + n] || diag2[r + c]) continue;
            cols[c] = diag1[r - c + n] = diag2[r + c] = true;
            dfs(r + 1, n, cols, diag1, diag2);
            cols[c] = diag1[r - c + n] = diag2[r + c] = false;
        }
    }
}

var totalNQueens = function(n) {
    let count = 0;
    const cols = new Array(n).fill(false);
    const diag1 = new Array(2 * n).fill(false);
    const diag2 = new Array(2 * n).fill(false);
    function backtrack(r) {
        if (r === n) {
            count++;
            return;
        }
        for (let c = 0; c < n; c++) {
            if (cols[c] || diag1[r - c + n] || diag2[r + c]) continue;
            cols[c] = diag1[r - c + n] = diag2[r + c] = true;
            backtrack(r + 1);
            cols[c] = diag1[r - c + n] = diag2[r + c] = false;
        }
    }
    backtrack(0);
    return count;
};
